head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vID;
scwin.vScrenID = "ULDSTF70071.xml";
scwin.fr_queryId; // 종목 query id
scwin.vBzProcsNo;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
// 종목
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISU_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 명칭값을 포함할 컨트롤	
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
    }
};




//상장신청인
scwin.fn_GetParUsrId = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_INTEG_USR_ID); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_EMP_NM); // 명칭값을 포함할 컨트롤	
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParUsrId = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_INTEG_USR_ID.setValue(arrPar[0].ISU_CD);
        txb_EMP_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
    }
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    var parentWin = $c.frame.path("../");
    scwin.vID = parentWin.clickID;
    var pGubun = parentWin.fn_pGubun;
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    var vIsuCd = parentWin.clickIsuCd;
    var vIsuNm = parentWin.clickIsuNm;
    var vUsrId = parentWin.clickIntegUsrId;
    var vIUsrNm = parentWin.clickIntegUsrNm;
    $c.stf.setObjectValue(txb_ISU_CD, vIsuCd);
    $c.stf.setObjectValue(txb_ISU_NM, vIsuNm);
    $c.stf.setObjectValue(txb_INTEG_USR_ID, vUsrId);
    $c.stf.setObjectValue(txb_EMP_NM, vIUsrNm);

    // 신규 팝업창으로 open 됐을 경우,
    if (pGubun == "I") {
        btn_delete.setDisabled(true);
        btn_delete.src = "../img/btn_delete_d.gif";
    } else if (pGubun == "D") {
        btn_insert.setDisabled(true);
        //btn_insert.src = "../img/btn_reg_d.gif"; // reg_d.gif 파일이 존재하지 않으므로 다른 이미지 파일로 대체
        btn_insert.src = "../img/btn_save_d.gif";

        // 종목,상장신청인 search disable 처리			
        img_SearchIsu.setDisabled(true);
        img_SearchUrs.setDisabled(true);
        img_SearchIsu.src = "../img/btn_search_d.gif";
        img_SearchUrs.src = "../img/btn_search_d.gif";
    } else {
        // just view screen. (not delete, not insert)

        btn_delete.setDisabled(true);
        btn_delete.src = "../img/btn_delete_d.gif";
        btn_insert.setDisabled(true);
        //btn_insert.src = "../img/btn_reg_d.gif";  // reg_d.gif 파일이 존재하지 않으므로 다른 이미지 파일로 대체
        btn_insert.src = "../img/btn_save_d.gif";

        // 종목,상장신청인 search disable 처리
        img_SearchIsu.setDisabled(true);
        img_SearchUrs.setDisabled(true);
        img_SearchIsu.src = "../img/btn_search_d.gif";
        img_SearchUrs.src = "../img/btn_search_d.gif";
    }
};
scwin.img_SearchIsu_onclick = async function() {
    // 기존값 초기화
    if ($c.stf.getObjectValue(txb_ISU_CD) != "") {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: setObjectValue(txb_ISU_CD) = "";*/
        X = ""; /*ORG SRC: setObjectValue(txb_ISU_NM) = "";*/ X = "";
    }

    //(종목명변경)종목코드 조회	
    fn_GetPar = fn_GetParIsuCd;
    fn_SetPar = fn_SetParIsuCd;
    scwin.fr_queryId = "lds.stf.digital.select.secuisuall_p2.condition";
    await $c.frame.CreateDialogFrame("ULDSTF70017_3.gfm", "../digital/ULDSTF70017_3.gfm", "종목 선택", 10, 10, 430, 550 + 30, "window");
};
scwin.img_SearchUrs_onclick = async function() {
    // 기존값 초기화
    if ($c.stf.getObjectValue(txb_INTEG_USR_ID) != "") {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: setObjectValue(txb_INTEG_USR_ID) = "";*/
        X = ""; /*ORG SRC: setObjectValue(txb_EMP_NM) = "";*/ X = "";
    }
    //상장신청인명 조회
    fn_GetParIsur = fn_GetParUsrId;
    fn_SetParIsur = fn_SetParUsrId;
    await $c.frame.CreateDialogFrame("ULDSTF70017_4.gfm", "../digital/ULDSTF70017_4.gfm", "상장신청인 선택", 10, 10, 430, 550 + 30, "window");
};
scwin.btn_insert_onclick = function() {
    // 등록 버튼
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("종목을 입력해주세요.");
        return;
    }
    if ($c.stf.getObjectValue(txb_INTEG_USR_ID) == "") {
        $c.win.alert("상장신청인을 입력해주세요.");
        return;
    }
    if (window.confirm("[등록]하시겠습니까?")) {
        //	dts_input.DataID =  "/digital/DigitalListinvstg.do?method=listDigitalAinvst&messageId=DIGITAL_AINVSTLIST_OUT";
        //	dts_input.reset();

        var isuCd = $c.stf.getObjectValue(txb_ISU_CD); // 종목cd
        var listTbClssCd = ""; // 상장유형분류코드
        var integUsrId = $c.stf.getObjectValue(txb_INTEG_USR_ID); // 상장신청인id
        var pubofrYn = ""; // 공모여부


        trs_Save.Action = $c.lcd.fn_encodeNSession("/digital/DigitalListinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=insertdigitalAIvst");
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_input)";
        trs_Save.Parameters = " ISU_CD=" + isuCd + ", INTEG_USR_ID=" + integUsrId + ", REG_ID=" + js_emp_no;
        trs_Save.Post();
    }
};
scwin.trs_Save_OnFail = function() {
    $c.lcd.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lcd.fn_alertMsg('S1');
    scwin.fn_parentRefresh();
    await $c.frame.CloseFrame();
};
scwin.btn_delete_onclick = function() {
    // 삭제 버튼

    if (window.confirm("[삭제]하시겠습니까?")) {
        var isuCd = $c.stf.getObjectValue(txb_ISU_CD); // 종목cd		
        var integUsrId = $c.stf.getObjectValue(txb_INTEG_USR_ID); // 상장신청인id

        trs_Save.Action = $c.lcd.fn_encodeNSession("/digital/DigitalListinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=updatedigitalAIvst");
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_input)";
        trs_Save.Parameters = "BZ_PROCS_NO=" + scwin.vBzProcsNo + ", ISU_CD=" + isuCd + ", INTEG_USR_ID=" + integUsrId + ", ADJPRN_ID=" + js_emp_no;
        trs_Save.Post();
    }
};
